// Shared by the tools/intl generators: the provenance header every generated .inc starts with.
import { createRequire } from 'node:module';

const require = createRequire(import.meta.url);

// "// Generated by tools/intl/<script> (cd tools/intl && node <script>) with node X (ICU Y, CLDR Z, tz T,
// Unicode U), cldr-core V, cldr-bcp47 W. Do not edit."
export function header(script) {
  const v = process.versions;
  const pkg = (name) => require(`${name}/package.json`).version;
  return [
    `// Generated by tools/intl/${script}: cd tools/intl && npm install && node ${script}`,
    `// node ${v.node} (ICU ${v.icu}, CLDR ${v.cldr}, tz ${v.tz}, Unicode ${v.unicode}); cldr-core ${pkg('cldr-core')}, cldr-bcp47 ${pkg('cldr-bcp47')}.`,
    '// Do not edit; re-run the script (output is deterministic).',
  ].join('\n');
}

// Byte-order comparison (no locale collation) for deterministic sorting.
export const cmp = (a, b) => (a < b ? -1 : a > b ? 1 : 0);

// The available locales: every language[-script][-region] combination (from the likely-subtags data) that node's
// Intl.NumberFormat resolves to itself; sorted.
export function availableLocales() {
  const likely = require('cldr-core/supplemental/likelySubtags.json').supplemental.likelySubtags;
  const langs = new Set(), scripts = new Set(), regions = new Set();
  for (const v of Object.values(likely)) {
    const [l, s, r] = v.split('-');
    langs.add(l);
    scripts.add(s);
    regions.add(r);
  }
  const exact = (t) => new Intl.NumberFormat(t).resolvedOptions().locale === t;
  const locales = [];
  for (const l of [...langs].sort(cmp)) {
    if (!exact(l)) continue;
    locales.push(l);
    for (const r of [...regions].sort(cmp)) if (exact(`${l}-${r}`)) locales.push(`${l}-${r}`);
    for (const s of [...scripts].sort(cmp)) {
      if (!exact(`${l}-${s}`)) continue;
      locales.push(`${l}-${s}`);
      for (const r of [...regions].sort(cmp)) if (exact(`${l}-${s}-${r}`)) locales.push(`${l}-${s}-${r}`);
    }
  }
  return locales.sort(cmp);
}

// The locale BestAvailableLocale falls back to: the last subtag removed (and a preceding singleton); null at the top.
export function parentOf(locale) {
  let pos = locale.lastIndexOf('-');
  if (pos < 0) return null;
  if (pos >= 2 && locale[pos - 2] === '-') pos -= 2;
  return locale.slice(0, pos);
}

// A UTF-16 C++ string literal body: ASCII printable as is, everything else as \x escapes.
export function u16(s) {
  let out = '';
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i);
    if (c >= 0x20 && c < 0x7f && c !== 0x22 && c !== 0x5c && c !== 0x3f) {
      out += s[i];
      continue;
    }
    out += `\\x${c.toString(16)}`;
    if (i + 1 < s.length && /[0-9a-fA-F]/.test(s[i + 1])) out += '""';
  }
  return out;
}

// The key a locale's data is stored under: the locale with its likely script inserted when that script is not its
// language's (zh-TW -> zh-Hant-TW, sr-ME -> sr-Latn-ME), so that truncation inherits from the right script.
// src/builtins/intl/locale_data.cpp (data::dataKey) computes the same from the likely-subtags data.
export function dataKey(locale) {
  const l = new Intl.Locale(locale);
  if (l.script || !l.region) return locale;
  const script = l.maximize().script;
  if (!script || script === new Intl.Locale(l.language).maximize().script) return locale;
  return `${l.language}-${script}-${l.region}${locale.slice(`${l.language}-${l.region}`.length)}`;
}
